function restoreArray(adjacentPairs: number[][]): number[] {
    const n = adjacentPairs.length + 1;
    const adj = new Map<number, number[]>();

    for (const [u, v] of adjacentPairs) {
        if (!adj.has(u)) adj.set(u, []);
        if (!adj.has(v)) adj.set(v, []);
        adj.get(u)!.push(v);
        adj.get(v)!.push(u);
    }

    let start: number = 0;
    for (const [key, list] of adj) {
        if (list.length === 1) {
            start = key;
            break;
        }
    }

    const result: number[] = [];
    const visited = new Set<number>();
    let cur = start;

    while (true) {
        result.push(cur);
        visited.add(cur);
        let next = -1;
        for (const nb of adj.get(cur)!) {
            if (!visited.has(nb)) {
                next = nb;
                break;
            }
        }
        if (next === -1) break;
        cur = next;
    }

    return result;
}
