function isSolvable(words: string[], result: string): boolean {
    let maxWordLen = 0;
    for (const w of words) {
        if (w.length > maxWordLen) maxWordLen = w.length;
    }
    if (result.length < maxWordLen) return false;

    const idxOf = new Map<string, number>();
    const isLeading: boolean[] = [];
    const ensure = (c: string, leading: boolean): void => {
        const existing = idxOf.get(c);
        if (existing === undefined) {
            idxOf.set(c, isLeading.length);
            isLeading.push(leading);
        } else if (leading) {
            isLeading[existing] = true;
        }
    };
    for (const w of words) {
        for (let i = 0; i < w.length; i++) ensure(w[i], i === 0);
    }
    for (let i = 0; i < result.length; i++) ensure(result[i], i === 0);

    const n = isLeading.length;
    if (n > 10) return false;

    const numCols = result.length;
    const colWords: number[][] = [];
    const colRes: number[] = [];
    for (let col = 0; col < numCols; col++) {
        const list: number[] = [];
        for (const w of words) {
            if (col < w.length) list.push(idxOf.get(w[w.length - 1 - col])!);
        }
        colWords.push(list);
        colRes.push(idxOf.get(result[result.length - 1 - col])!);
    }

    const assign = new Array<number>(n).fill(-1);
    const used = new Array<boolean>(10).fill(false);

    const dfs = (col: number, i: number, sum: number, carry: number): boolean => {
        if (col === numCols) return carry === 0;
        const list = colWords[col];
        if (i < list.length) {
            const c = list[i];
            const cur = assign[c];
            if (cur !== -1) return dfs(col, i + 1, sum + cur, carry);
            const lead = isLeading[c];
            for (let d = 0; d < 10; d++) {
                if (used[d] || (d === 0 && lead)) continue;
                assign[c] = d;
                used[d] = true;
                if (dfs(col, i + 1, sum + d, carry)) return true;
                used[d] = false;
                assign[c] = -1;
            }
            return false;
        }
        const total = sum + carry;
        const digit = total % 10;
        const nextCarry = (total - digit) / 10;
        const resChar = colRes[col];
        const cur = assign[resChar];
        if (cur !== -1) {
            return cur === digit && dfs(col + 1, 0, 0, nextCarry);
        }
        if (used[digit] || (digit === 0 && isLeading[resChar])) return false;
        assign[resChar] = digit;
        used[digit] = true;
        if (dfs(col + 1, 0, 0, nextCarry)) return true;
        used[digit] = false;
        assign[resChar] = -1;
        return false;
    };

    return dfs(0, 0, 0, 0);
}
```

