                charIndex.set(c, chars.length);
                chars.push(c);
            }
        }
    }
    for (const c of result) {
        if (!charIndex.has(c)) {
            charIndex.set(c, chars.length);
            chars.push(c);
        }
    }
    if (chars.length > 10) return false;

    const isLeading = new Array<boolean>(chars.length).fill(false);
    for (const w of words) isLeading[charIndex.get(w[0])!] = true;
    isLeading[charIndex.get(result[0])!] = true;

    const assign = new Array<number>(chars.length).fill(-1);
    const usedDigit = new Array<boolean>(10).fill(false);

    const totalCols = result.length;

    const dfs = (col: number, carry: number): boolean => {
        if (col === totalCols) return carry === 0;

        // gather word chars in this column
        // process recursively
        const wordChars: number[] = []; // indices
        for (const w of words) {
            if (col < w.length) {
                wordChars.push(charIndex.get(w[w.length - 1 - col])!);
            }
        }
        const resChar = charIndex.get(result[result.length - 1 - col])!;

        const sumSoFar = { val: 0 }; // or use closure variable

        const processWords = (idx: number, sum: number): boolean => {
