                    if (usedDigit[digit]) return false;
                    if (digit === 0 && isLeading[resChar]) return false;
                    assign[resChar] = digit;
                    usedDigit[digit] = true;
                    if (dfs(col + 1, newCarry)) return true;
                    assign[resChar] = -1;
                    usedDigit[digit] = false;
                    return false;
                } else {
                    if (assign[resChar] !== digit) return false;
                    return dfs(col + 1, newCarry);
                }
            }
            const c = wordChars[idx];
            if (assign[c] !== -1) {
                return processWords(idx + 1, sum + assign[c]);
