                usedDigit[d] = true;
                if (processWords(idx + 1, sum + d)) return true;
                assign[c] = -1;
                usedDigit[d] = false;
            }
            return false;
        };

        return processWords(0, 0);
    };

    return dfs(0, 0);
}
