    let maxWordLen = 0;
    for (const w of words) if (w.length > maxWordLen) maxWordLen = w.length;
    if (result.length < maxWordLen) return false;

    const idxOf = new Map<string, number>();
    const isLeading: boolean[] = [];
    const ensure = (c: string, leading: boolean): number => {
        let v = idxOf.get(c);
        if (v === undefined) {
            v = idxOf.size;
            idxOf.set(c, v);
            isLeading.push(leading);
        } else if (leading) {
            isLeading[v] = true;
        }
        return v;
    };
    for (const w of words) {
        for (let i = 0; i < w.length; i++) ensure(w[i], i === 0);
    }
    for (let i = 0; i < result.length; i++) ensure(result[i], i === 0);
    const n = idxOf.size;
    if (n > 10) return false;

    const numCols = result.length;
    const colWords: number[][] = [];
    const colRes: number[] = [];
    for (let col = 0; col < numCols; col++) {
        const list: number[] = [];
        for (const w of words) {
            if (col < w.length) list.push(idxOf.get(w[w.length - 1 - col])!);
        }
        colWords.push(list);
        colRes.push(idxOf.get(result[result.length - 1 - col])!);
