function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const f = (s: string): number => {
        let ch = 'z', cnt = 0;
        for (const c of s) {
            if (c < ch) { ch = c; cnt = 1; }
            else if (c === ch) cnt++;
        }
        return cnt;
    };
    const wf = words.map(f).sort((a, b) => a - b);
    return queries.map(q => {
        const v = f(q);
        let lo = 0, hi = wf.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (wf[mid] <= v) lo = mid + 1; else hi = mid;
        }
        return wf.length - lo;
    });
}
