function countCollisions(directions: string): number {
    const n = directions.length;

    // Skip leading 'L' cars — they drive off to the left and never collide.
    let left = 0;
    while (left < n && directions[left] === 'L') left++;

    // Skip trailing 'R' cars — they drive off to the right and never collide.
    let right = n - 1;
    while (right >= 0 && directions[right] === 'R') right--;

    // Every remaining moving car ('L' or 'R') will eventually crash into
    // something (a stationary car or a pileup). Each crashing car contributes
    // exactly 1 to the total: an R-L head-on counts 2 (one per car), and a
    // moving-vs-stationary crash counts 1 (the mover).
    let count = 0;
    for (let i = left; i <= right; i++) {
        if (directions[i] !== 'S') count++;
    }

    return count;
}
