class CustomStack {
    private stack: number[];
    private add: number[];
    private maxSize: number;

    constructor(maxSize: number) {
        this.stack = [];
        this.add = new Array(maxSize).fill(0);
        this.maxSize = maxSize;
    }

    push(x: number): void {
        if (this.stack.length < this.maxSize) {
            this.stack.push(x);
            this.add[this.stack.length - 1] = 0;
        }
    }

    pop(): number {
        if (this.stack.length === 0) return -1;
        const i = this.stack.length - 1;
        const value = this.stack[i] + this.add[i];
        if (i > 0) {
            this.add[i - 1] += this.add[i];
        }
        this.add[i] = 0;
        this.stack.pop();
        return value;
    }

    increment(k: number, val: number): void {
        const i = Math.min(k, this.stack.length) - 1;
        if (i >= 0) {
            this.add[i] += val;
        }
    }
}
