function maxCompatibilitySum(students: number[][], mentors: number[][]): number {
    const m = students.length;
    const n = students[0].length;

    // Precompute compatibility scores
    const score: number[][] = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) s++;
            }
            score[i][j] = s;
        }
    }

    // dp[mask] = max score assigning first popcount(mask) students to mentors in mask
    const size = 1 << m;
    const dp: number[] = new Array(size).fill(0);

    for (let mask = 1; mask < size; mask++) {
        const studentIdx = popcount(mask) - 1;
        for (let j = 0; j < m; j++) {
            if (mask & (1 << j)) {
                const prev = mask ^ (1 << j);
                const val = dp[prev] + score[studentIdx][j];
                if (val > dp[mask]) dp[mask] = val;
            }
        }
    }

    return dp[size - 1];
}

function popcount(x: number): number {
    let c = 0;
    while (x) {
        x &= x - 1;
        c++;
    }
    return c;
}
```

