function maxEqualFreq(nums: number[]): number {
    const count = new Map<number, number>();
    const freqCount = new Map<number, number>();
    let maxFreq = 0;
    let ans = 0;

    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        const c = count.get(x) || 0;
        if (c > 0) {
            freqCount.set(c, (freqCount.get(c) || 0) - 1);
        }
        count.set(x, c + 1);
        freqCount.set(c + 1, (freqCount.get(c + 1) || 0) + 1);
        maxFreq = Math.max(maxFreq, c + 1);

        const n = i + 1;
        if (
            maxFreq === 1 ||
            freqCount.get(maxFreq)! * maxFreq === n - 1 ||
            (freqCount.get(maxFreq)! === 1 && (freqCount.get(maxFreq - 1)! + 1) * (maxFreq - 1) === n - 1)
        ) {
            ans = n;
        }
    }
    return ans;
}
```

