function maxEqualFreq(nums: number[]): number {
    const MAXV = 100001;
    const count = new Array<number>(MAXV).fill(0);
    const freqCount = new Array<number>(MAXV).fill(0);
    let maxFreq = 0;
    let ans = 0;
    const n = nums.length;

    for (let i = 0; i < n; i++) {
        const x = nums[i];
        const c = count[x];
        count[x] = c + 1;
        if (c > 0) freqCount[c]--;
        freqCount[c + 1]++;
        if (c + 1 > maxFreq) maxFreq = c + 1;

        const len = i + 1;
        const fMax = freqCount[maxFreq];
        if (
            maxFreq === 1 ||
            fMax * maxFreq === len - 1 ||
            (fMax === 1 && (freqCount[maxFreq - 1] + 1) * (maxFreq - 1) === len - 1)
        ) {
            ans = len;
        }
    }
    return ans;
}
```

