```typescript
function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const valid: number[] = [];
    for (let i = 0; i < m; i++) {
        let v = 0;
        for (let j = 0; j < n; j++) {
            if (seats[i][j] === '.') v |= (1 << j);
        }
        valid.push(v);
    }

    const popcount = (x: number): number => {
        let c = 0;
        while (x) { x &= x - 1; c++; }
        return c;
    };

    // Precompute all valid masks for a row: subset of valid, no two adjacent
    const isValidMask = (mask: number, validRow: number): boolean => {
        if ((mask & validRow) !== mask) return false;
        if ((mask & (mask << 1)) !== 0) return false;
        return true;
    };

    let prev = new Array(1 << n).fill(-1);
    // Initialize row 0
    for (let mask = 0; mask < (1 << n); mask++) {
        if (isValidMask(mask, valid[0])) prev[mask] = popcount(mask);
    }

    for (let i = 1; i < m; i++) {
        const cur = new Array(1 << n).fill(-1);
        for (let mask = 0; mask < (1 << n); mask++) {
            if (!isValidMask(mask, valid[i])) continue;
            const cnt = popcount(mask);
            let best = -1;
            for (let p = 0; p < (1 << n); p++) {
                if (prev[p] < 0) continue;
                if ((mask & (p << 1)) !== 0) continue;
                if ((mask & (p >> 1)) !== 0) continue;
                if (prev[p] + cnt > best) best = prev[p] + cnt;
            }
            cur[mask] = best;
        }
        prev = cur;
    }

    let ans = 0;
    for (const v of prev) if (v > ans) ans = v;
    return ans;
}
