function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const full = 1 << n;

    // Bitmask of available seats per row
    const valid: number[] = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        let v = 0;
        for (let j = 0; j < n; j++) {
            if (seats[i][j] === '.') v |= 1 << j;
        }
        valid[i] = v;
    }

    const popcount = (x: number): number => {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    };

    // A row arrangement is valid if it only uses available seats
    // and no two students sit adjacent horizontally.
    const ok = (mask: number, row: number): boolean =>
        (mask & valid[row]) === mask && (mask & (mask << 1)) === 0;

    // dp[mask] = max students up to current row, current row arranged as `mask`
    let dp = new Array<number>(full).fill(-1);
    for (let mask = 0; mask < full; mask++) {
        if (ok(mask, 0)) dp[mask] = popcount(mask);
    }

    for (let i = 1; i < m; i++) {
        const ndp = new Array<number>(full).fill(-1);
        for (let mask = 0; mask < full; mask++) {
            if (!ok(mask, i)) continue;
            const cnt = popcount(mask);
            let best = -1;
            for (let p = 0; p < full; p++) {
                if (dp[p] < 0) continue;
                // No student in current row may sit diagonally (upper-left / upper-right)
