                if ((mask & (p << 1)) !== 0) continue;
                if ((mask & (p >> 1)) !== 0) continue;
                const val = dp[p] + cnt;
                if (val > best) best = val;
            }
            ndp[mask] = best;
        }
        dp = ndp;
    }

    let ans = 0;
    for (const v of dp) if (v > ans) ans = v;
    return ans;
}
