```typescript
function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const prefix: number[] = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    const sumOf = (start: number, len: number) => prefix[start + len] - prefix[start];

    const helper = (lenA: number, lenB: number): number => {
        let best = 0;
        let maxA = 0; // max sum of lenA subarray ending before current lenB subarray starts
        // iterate over start of lenB subarray
        for (let i = lenA; i + lenB <= n; i++) {
            // lenA subarray can end at position i (exclusive), i.e., start at most i - lenA
            // update maxA with lenA subarray ending at index i-1 (start i - lenA)
            maxA = Math.max(maxA, sumOf(i - lenA, lenA));
            best = Math.max(best, maxA + sumOf(i, lenB));
        }
        return best;
    };

    return Math.max(helper(firstLen, secondLen), helper(secondLen, firstLen));
};
```

