```typescript
function minOperations(s: string): number {
    let count0 = 0; // changes needed for pattern starting with '0'
    for (let i = 0; i < s.length; i++) {
        const expected = i % 2 === 0 ? '0' : '1';
        if (s[i] !== expected) count0++;
    }
    return Math.min(count0, s.length - count0);
}
```

