function minDays(grid: number[][]): number {
    const m = grid.length;
    const n = grid[0].length;
    const dirs: number[][] = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    const countIslands = (g: number[][]): number => {
        const visited: boolean[] = new Array(m * n).fill(false);
        let count = 0;
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (g[i][j] === 1 && !visited[i * n + j]) {
                    count++;
                    const stack: number[] = [i * n + j];
                    visited[i * n + j] = true;
                    while (stack.length > 0) {
                        const cur = stack.pop()!;
                        const x = Math.floor(cur / n);
                        const y = cur % n;
                        for (const [dx, dy] of dirs) {
                            const nx = x + dx;
                            const ny = y + dy;
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && g[nx][ny] === 1 && !visited[nx * n + ny]) {
                                visited[nx * n + ny] = true;
                                stack.push(nx * n + ny);
                            }
                        }
                    }
                }
            }
        }
        return count;
    };

    // 0 days: already disconnected (0 or >= 2 islands)
    if (countIslands(grid) !== 1) return 0;

    // 1 day: try removing each land cell; if result is not exactly one island, it's disconnected
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;
                const c = countIslands(grid);
                grid[i][j] = 1;
                if (c !== 1) return 1;
            }
        }
    }

    // Otherwise 2 days always suffice:
    // - if the single island has an articulation-like structure, some pair works;
    // - if it is 2-connected, the topmost-leftmost cell has both right and down
    //   neighbors (degree >= 2 with only those possible directions), and removing
    //   those two neighbors isolates it, disconnecting the grid.
    return 2;
}
