function minDays(grid: number[][]): number {
    const m = grid.length;
    const n = grid[0].length;

    const countIslands = (g: number[][]): number => {
        const visited: boolean[][] = Array.from({ length: m }, () => new Array(n).fill(false));
        let count = 0;
        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (g[i][j] === 1 && !visited[i][j]) {
                    count++;
                    // BFS/DFS
                    const stack: number[][] = [[i, j]];
                    visited[i][j] = true;
                    while (stack.length > 0) {
                        const [x, y] = stack.pop()!;
                        for (const [dx, dy] of dirs) {
                            const nx = x + dx, ny = y + dy;
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && g[nx][ny] === 1 && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                stack.push([nx, ny]);
                            }
                        }
                    }
                }
            }
        }
        return count;
    };

    if (countIslands(grid) !== 1) return 0;

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;
                const c = countIslands(grid);
                grid[i][j] = 1;
                if (c !== 1) return 1;
            }
        }
    }

    return 2;
}
```

