function minDays(bloomDay: number[], m: number, k: number): number {
    const n = bloomDay.length;
    if (m * k > n) return -1;

    let lo = Math.min(...bloomDay); // careful: spread on 10^5 elements is fine
    let hi = Math.max(...bloomDay);

    const canMake = (day: number): boolean => {
        let bouquets = 0;
        let consecutive = 0;
        for (let i = 0; i < n; i++) {
            if (bloomDay[i] <= day) {
                consecutive++;
                if (consecutive === k) {
                    bouquets++;
                    consecutive = 0;
                    if (bouquets >= m) return true;
                }
            } else {
                consecutive = 0;
            }
        }
        return bouquets >= m;
    };

    while (lo < hi) {
        const mid = lo + Math.floor((hi - lo) / 2);
        if (canMake(mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
};
```

