function canPartitionKSubsets(nums: number[], k: number): boolean {
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % k !== 0) return false;
    const target = total / k;
    nums.sort((a, b) => b - a);
    if (nums[0] > target) return false;
    const n = nums.length;
    const used = new Array(n).fill(false);

    function backtrack(start: number, remaining: number, bucketsLeft: number): boolean {
        if (bucketsLeft === 0) return true;
        if (remaining === 0) return backtrack(0, target, bucketsLeft - 1);
        for (let i = start; i < n; i++) {
            if (used[i] || nums[i] > remaining) continue;
            // skip duplicates
            if (i > start && nums[i] === nums[i-1] && !used[i-1]) continue;
            used[i] = true;
            if (backtrack(i + 1, remaining - nums[i], bucketsLeft)) return true;
            used[i] = false;
            if (remaining === target) return false; // first element of bucket failed
        }
        return false;
    }
    return backtrack(0, target, k);
