```typescript
function maxSizeSlices(slices: number[]): number {
    const m = slices.length;
    const n = m / 3;

    // Max sum picking exactly `n` pairwise non-adjacent elements from linear array `arr`.
    const bestLinear = (arr: number[]): number => {
        const len = arr.length;
        const NEG = -Infinity;
        let dpPrev2 = new Array<number>(n + 1).fill(NEG); // dp[i-2][*]
