        const dpPrev2 = new Array<number>(n + 1).fill(NEG);
        const dpPrev1 = new Array<number>(n + 1).fill(NEG);
        dpPrev2[0] = 0;               // dp[0][*]
        dpPrev1[0] = 0;               // dp[1][*]
        dpPrev1[1] = arr[0];
        for (let i = 2; i <= len; i++) {
            const dpCur = new Array<number>(n + 1).fill(NEG);
            const v = arr[i - 1];
            for (let j = 0; j <= n; j++) {
