function maxSizeSlices(slices: number[]): number {
    const m = slices.length;
    const n = m / 3;

    // Returns the maximum sum obtainable by picking exactly `n` pairwise
    // non-adjacent elements from the linear array `arr`.
    const bestLinear = (arr: number[]): number => {
        const len = arr.length;
        const NEG = -Infinity;
        // Rolling DP over prefix length; index = number of picked elements (0..n).
        let dpPrev2 = new Array<number>(n + 1).fill(NEG); // dp[i-2]
        let dpPrev1 = new Array<number>(n + 1).fill(NEG); // dp[i-1]
        dpPrev2[0] = 0;      // dp[0][0] = 0
        dpPrev1[0] = 0;      // dp[1][0] = 0
        dpPrev1[1] = arr[0]; // dp[1][1] = arr[0]
        for (let i = 2; i <= len; i++) {
            const dpCur = new Array<number>(n + 1).fill(NEG);
            const v = arr[i - 1];
            for (let j = 0; j <= n; j++) {
                let bestVal = dpPrev1[j]; // skip arr[i-1]
                if (j > 0) {
                    const take = dpPrev2[j - 1] + v; // take arr[i-1]
                    if (take > bestVal) bestVal = take;
                }
                dpCur[j] = bestVal;
            }
            dpPrev2 = dpPrev1;
            dpPrev1 = dpCur;
        }
        return dpPrev1[n];
    };

    // Circular array: first and last are adjacent, so an optimal selection
    // excludes at least one of them. Solve both linear variants.
    return Math.max(
        bestLinear(slices.slice(0, m - 1)),
        bestLinear(slices.slice(1))
    );
}
```

