class Solution {
    private map: Map<number, number[]>;

    constructor(nums: number[]) {
        this.map = new Map<number, number[]>();
        for (let i = 0; i < nums.length; i++) {
            const arr = this.map.get(nums[i]);
            if (arr) {
                arr.push(i);
            } else {
                this.map.set(nums[i], [i]);
            }
