function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const size = (n + 1) * (n + 1);
    const parent = new Array<number>(size);
    for (let i = 0; i < size; i++) parent[i] = i;

    function find(x: number): number {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a: number, b: number): boolean {
        const ra = find(a), rb = find(b);
        if (ra === rb) return false;
        parent[ra] = rb;
        return true;
    }

    const id = (r: number, c: number) => r * (n + 1) + c;

    // Connect all border points to super node 0
    for (let r = 0; r <= n; r++) {
        for (let c = 0; c <= n; c++) {
            if (r === 0 || r === n || c === 0 || c === n) {
                union(0, id(r, c));
            }
        }
    }

    let regions = 1; // components excluding node 0's component start with the outer region

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];
            if (ch === '/') {
                // connect top-right and bottom-left
                if (!union(id(r, c + 1), id(r + 1, c))) regions++;
            } else if (ch === '\\') {
                // connect top-left and bottom-right
                if (!union(id(r, c), id(r + 1, c + 1))) regions++;
            }
        }
    }

    return regions;
}
