    dp[0][0] = true;

    // Empty string vs pattern: only patterns like a*, a*b*, a*b*c* can match
    for (let j = 1; j <= n; j++) {
        if (p[j - 1] === '*') {
            dp[0][j] = dp[0][j - 2];
        }
    }

