    const memo: (number | undefined)[][][] = Array.from({length: n}, () => 
        Array.from({length: n}, () => new Array(n + 1).fill(undefined))
    );

    function helper(i: number, j: number, len: number): boolean {
        if (len === 1) return s1[i] === s2[j];

        const cached = memo[i][j][len];
        if (cached !== undefined) return cached === 1;

        // frequency check
        const count = new Array(26).fill(0);
        for (let k = 0; k < len; k++) {
            count[s1.charCodeAt(i + k) - 97]++;
            count[s2.charCodeAt(j + k) - 97]--;
        }
        let feasible = true;
        for (let c = 0; c < 26; c++) {
            if (count[c] !== 0) {
                feasible = false;
                break;
            }
        }
        if (!feasible) {
            memo[i][j][len] = 0;
            return false;
        }

        for (let split = 1; split < len; split++) {
            // no swap
            if (helper(i, j, split) && helper(i + split, j + split, len - split)) {
                memo[i][j][len] = 1;
                return true;
            }
            // swap
            if (helper(i, j + len - split, split) && helper(i + split, j, len - split)) {
                memo[i][j][len] = 1;
                return true;
            }
        }

        memo[i][j][len] = 0;
        return false;
    }

    return helper(0, 0, n);
