- Two strings are scrambles if they're equal, or if there's a split point where either the "no-swap" pairing (left↔left, right↔right) or the "swap" pairing (left↔right) both hold recursively.
- Use memoization on `(i, j, len)` representing comparing `s1[i..i+len)` with `s2[j..j+len)`.
- Prune aggressively: if substrings are equal → true; if character frequency counts differ → false (this prunes the exponential search massively).

Verification with example 1: `"great"` vs `"rgeat"` — split at 2: `"gr"` scrambles to `"rg"` (swap at split 1), and `"eat" === "eat"` → true. Example 3: length 1, direct char comparison → true.

```typescript
function isScramble(s1: string, s2: string): boolean {
    const n = s1.length;
    if (n !== s2.length) return false;
    if (s1 === s2) return true;

    // memo[i][j][len]: -1 unknown, 0 false, 1 true
    // represents whether s1[i..i+len) can be scrambled into s2[j..j+len)
    const memo: Int8Array[][] = [];
    for (let i = 0; i < n; i++) {
        const row: Int8Array[] = [];
        for (let j = 0; j < n; j++) {
            row.push(new Int8Array(n + 1).fill(-1));
        }
        memo.push(row);
    }

    const helper = (i: number, j: number, len: number): boolean => {
        if (len === 1) return s1[i] === s2[j];

        const cached = memo[i][j][len];
        if (cached !== -1) return cached === 1;

        // Combined equality + frequency check (pruning)
        const count = new Int32Array(26);
        let equal = true;
        for (let k = 0; k < len; k++) {
            const a = s1.charCodeAt(i + k);
            const b = s2.charCodeAt(j + k);
            if (a !== b) equal = false;
            count[a - 97]++;
            count[b - 97]--;
        }

        if (equal) {
            memo[i][j][len] = 1;
            return true;
        }

        for (let c = 0; c < 26; c++) {
            if (count[c] !== 0) {
                memo[i][j][len] = 0;
                return false;
            }
        }

        for (let split = 1; split < len; split++) {
            // No swap: left with left, right with right
            if (helper(i, j, split) && helper(i + split, j + split, len - split)) {
                memo[i][j][len] = 1;
                return true;
            }
            // Swap: left of s1 with right of s2, right of s1 with left of s2
            if (helper(i, j + len - split, split) && helper(i + split, j, len - split)) {
                memo[i][j][len] = 1;
                return true;
            }
        }

        memo[i][j][len] = 0;
        return false;
    };

    return helper(0, 0, n);
}
```

