```typescript
function shiftGrid(grid: number[][], k: number): number[][] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    k = k % total;

    const result: number[][] = Array.from({ length: m }, () => new Array(n).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const flatIdx = i * n + j;
            // The element at flatIdx in the original moves to (flatIdx + k) % total
            // So result position (flatIdx + k) % total gets grid[i][j]
            const newFlat = (flatIdx + k) % total;
            const newRow = Math.floor(newFlat / n);
            const newCol = newFlat % n;
            result[newRow][newCol] = grid[i][j];
        }
    }

    return result;
}
```

