function spiralMatrixIII(rows: number, cols: number, rStart: number, cStart: number): number[][] {
    const result: number[][] = [[rStart, cStart]];
    const directions: number[][] = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // east, south, west, north
    let r = rStart;
    let c = cStart;
    let stepLength = 1;
    let dirIndex = 0;

    while (result.length < rows * cols) {
        for (let k = 0; k < 2; k++) {
            const dr = directions[dirIndex % 4][0];
            const dc = directions[dirIndex % 4][1];
            for (let i = 0; i < stepLength; i++) {
                r += dr;
                c += dc;
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    result.push([r, c]);
                }
            }
            dirIndex++;
        }
        stepLength++;
    }

    return result;
}
```

