function minStickers(stickers: string[], target: string): number {
    const n = target.length;
    const full = (1 << n) - 1;

    // Precompute sticker counts as Int32Array(26) or count only relevant letters
    const stickerCounts: number[][] = [];
    for (const s of stickers) {
        const cnt = new Array(26).fill(0);
        for (const ch of s) cnt[ch.charCodeAt(0) - 97]++;
        stickerCounts.push(cnt);
    }

    const INF = Number.MAX_SAFE_INTEGER; // or a large number
    const dp = new Array(1 << n).fill(INF);
    dp[0] = 0;

    for (let mask = 0; mask <= full; mask++) {
        if (dp[mask] === INF) continue;
        // find first uncovered position
        let i = 0;
        while (i < n && (mask & (1 << i))) i++;
        if (i >= n) continue; // full
        const c = target.charCodeAt(i) - 97;
        for (const cnt of stickerCounts) {
            if (cnt[c] === 0) continue;
            // apply sticker
