```typescript
function minStickers(stickers: string[], target: string): number {
    const n = target.length;
    const FULL = (1 << n) - 1;
    const INF = 0x3f3f3f3f;

    // Assign ids to letters occurring in target
    const letterId = new Int16Array(26).fill(-1);
    let K = 0;
    const posLetter = new Int16Array(n);
    for (let i = 0; i < n; i++) {
        const c = target.charCodeAt(i) - 97;
        if (letterId[c] === -1) letterId[c] = K++;
        posLetter[i] = letterId[c];
    }

    // Build count vectors over the K relevant letters
    const raw: number[][] = [];
    for (const s of stickers) {
        const cnt = new Array<number>(K).fill(0);
        for (let i = 0; i < s.length; i++) {
            const id = letterId[s.charCodeAt(i) - 97];
            if (id >= 0) cnt[id]++;
        }
        let useful = false;
        for (let k = 0; k < K; k++) if (cnt[k] > 0) { useful = true; break; }
        if (useful) raw.push(cnt);
    }

    // Deduplicate identical stickers
    const seen = new Set<string>();
    const unique: number[][] = [];
    for (const cnt of raw) {
        const key = cnt.join(',');
        if (!seen.has(key)) {
            seen.add(key);
            unique.push(cnt);
        }
    }

    // Remove dominated stickers
    const vecs: number[][] = [];
    for (let i = 0; i < unique.length; i++) {
        let dominated = false;
        for (let j = 0; j < unique.length && !dominated; j++) {
            if (i === j) continue;
            const a = unique[i];
            const b = unique[j];
            let ok = true;
            for (let k = 0; k < K; k++) {
                if (b[k] < a[k]) { ok = false; break; }
            }
            if (ok) dominated = true;
        }
        if (!dominated) vecs.push(unique[i]);
    }

    // Bitmask DP
    const size = 1 << n;
    const dp = new Int32Array(size).fill(INF);
    dp[0] = 0;

    const avail = new Array<number>(K);

    for (let mask = 0; mask < size; mask++) {
        const cur = dp[mask];
        if (cur >= INF) continue;
        let i = 0;
        while ((mask & (1 << i)) !== 0) i++;
        if (i >= n) continue;
        const need = posLetter[i];
        for (const cnt of vecs) {
            if (cnt[need] === 0) continue;
            for (let k = 0; k < K; k++) avail[k] = cnt[k];
            let newMask = mask;
            for (let j = i; j < n; j++) {
                const bit = 1 << j;
                if ((newMask & bit) !== 0) continue;
                const id = posLetter[j];
                if (avail[id] > 0) {
                    avail[id]--;
                    newMask |= bit;
                }
            }
            const cand = cur + 1;
            if (cand < dp[newMask]) dp[newMask] = cand;
        }
    }

    return dp[FULL] >= INF ? -1 : dp[FULL];
}
```

