class StreamChecker {
    private root: TrieNode = new TrieNode();
    private maxLen = 0;
    private stream: string[] = [];

    constructor(words: string[]) {
        // Build trie of reversed words so suffix matching becomes prefix matching
        for (const word of words) {
            if (word.length > this.maxLen) {
                this.maxLen = word.length;
            }
            let node = this.root;
            for (let i = word.length - 1; i >= 0; i--) {
                const idx = word.charCodeAt(i) - 97;
                if (node.children[idx] === null) {
                    node.children[idx] = new TrieNode();
                }
                node = node.children[idx]!;
            }
            node.isWord = true;
        }
    }

    query(letter: string): boolean {
        this.stream.push(letter);
        if (this.stream.length > this.maxLen) {
            this.stream.shift();
        }
        let node = this.root;
        // Walk the trie backwards over the recent stream characters
        for (let i = this.stream.length - 1; i >= 0; i--) {
            const idx = this.stream[i].charCodeAt(0) - 97;
            const next = node.children[idx];
            if (next === null) {
                return false;
            }
            node = next;
            if (node.isWord) {
                return true;
            }
        }
        return false;
    }
}

