function strWithout3a3b(a: number, b: number): string {
    let countA = a;
    let countB = b;
    const chars: string[] = [];

    while (countA > 0 || countB > 0) {
        let writeA: boolean;
        const n = chars.length;
        if (n >= 2 && chars[n - 1] === chars[n - 2]) {
            // Last two characters are identical; must write the other one.
            writeA = chars[n - 1] === 'b';
        } else {
            // Write the character with the larger (or equal) remaining count.
            writeA = countA >= countB;
        }
        if (writeA) {
            chars.push('a');
            countA--;
        } else {
            chars.push('b');
            countB--;
        }
    }

    return chars.join('');
}
