```typescript
function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;
    const adj: number[][] = new Array(n);
    for (let i = 0; i < n; i++) adj[i] = [];
    for (let i = 0; i < edges.length; i++) {
        const u = edges[i][0];
        const v = edges[i][1];
        adj[u].push(v);
        adj[v].push(u);
    }

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const coprimeLists: number[][] = new Array(51);
    for (let a = 1; a <= 50; a++) {
        const lst: number[] = [];
        for (let b = 1; b <= 50; b++) {
            if (gcd(a, b) === 1) lst.push(b);
        }
        coprimeLists[a] = lst;
    }

    const ans: number[] = new Array(n).fill(-1);
    const lastDepth = new Int32Array(51).fill(-1);
    const lastNode = new Int32Array(51).fill(-1);

    const STRIDE = 6;
    const stack = new Int32Array((2 * n + 2) * STRIDE);
    let sp = 0;
    stack[0] = 0;  // type: 0 = enter
    stack[1] = 0;  // node
    stack[2] = -1; // parent
    stack[3] = 0;  // depth
    stack[4] = -1;
    stack[5] = -1;
    sp = 1;

    while (sp > 0) {
        sp--;
        const base = sp * STRIDE;
        const type = stack[base];
        const node = stack[base + 1];
        const parent = stack[base + 2];
        const depth = stack[base + 3];
        const v = nums[node];

        if (type === 1) {
            // exit: restore previous state for this value
            lastDepth[v] = stack[base + 4];
            lastNode[v] = stack[base + 5];
        } else {
            // find closest coprime ancestor on current path
            const list = coprimeLists[v];
            let bestDepth = -1;
            let bestNode = -1;
            for (let i = 0; i < list.length; i++) {
                const w = list[i];
                if (lastDepth[w] > bestDepth) {
                    bestDepth = lastDepth[w];
                    bestNode = lastNode[w];
                }
            }
            if (bestDepth >= 0) ans[node] = bestNode;

            // convert this slot into an exit frame (all reads already done)
            stack[base] = 1;
            stack[base + 1] = node;
            stack[base + 2] = -1;
            stack[base + 3] = depth;
            stack[base + 4] = lastDepth[v];
            stack[base + 5] = lastNode[v];
            sp++;

            // record current node for its value
            lastDepth[v] = depth;
            lastNode[v] = node;

            // push children
            const children = adj[node];
            for (let i = 0; i < children.length; i++) {
